define({"topics":[{"title":"Doing DQA calibration with the DQA III phantom","shortdesc":"<p class=\"shortdesc\">The DQA tool determines correct gradient polarity and correct gradient wiring by scanning a series of axial and coronal images of the DQA III phantom for systems below sentence MR 31.0 or sites that do not have a 17cm Sphere with Spout (SWS) phantom.<\/p>","href":"t_DoingDQACalibration_2.html","attributes":{"data-id":"id_2001635"},"menu":{"hasChildren":false},"tocID":"id_2001635-d46e14941","topics":[]},{"title":"Doing DQA calibration <span class=\"ph\">with the Sphere With Spout (SWS) phantom<\/span>","shortdesc":"<p class=\"shortdesc\">Details the steps needed to run the Gradient Calibration Tool (GCT) for systems running MR31.0 and higher<span class=\"ph\"> and that possess the 17cm Sphere with Spout (SWS) phantom<\/span>. GCT does the same checks and produces the same output as DQA.<\/p>","href":"t_DoingDQACalibrationsforMR31andHigher_2.html","attributes":{"data-id":"id_2068424"},"menu":{"hasChildren":false},"tocID":"id_2068424-d46e15046","topics":[]}]});